import { throttle } from 'lodash-es';
import { useCallback, useEffect } from 'react';

const FPS = 1000 / 60; // in ms

/**
 * Add event listener into Document related to toolbar actions.

 * @param eventName - DOM Event name EG: keydown, wheel, etc.
 * @param callback - behavior that will be executed in the defined event
 * @param callbackCondition - callback condition
 * @param eventCondition - event condition
 * @param element - the element where the event occurs
 */
export function useToolbarEvent<T extends Event>(
  eventName: string,
  callback: () => void,
  callbackCondition: (event: T) => boolean,
  eventCondition: boolean | undefined,
  element?: HTMLDivElement,
): void {
  const eventHandler = useCallback(
    (event: T) => {
      if (callbackCondition(event)) {
        event.preventDefault();
        callback();
      }
    },
    [callbackCondition, callback],
  );

  useEffect(() => {
    const throttleHandler = throttle((event) => eventHandler(event), FPS);
    // Wheel & keyboard events need not to be passive as we're not treating it as a default behaviour.
    const isPassive = eventName !== 'wheel' && eventName !== 'keydown';

    if (eventCondition) {
      (element ?? document).addEventListener(eventName, throttleHandler, {
        passive: isPassive,
      });
    }

    return () => {
      (element ?? document).removeEventListener(eventName, throttleHandler);
    };
  }, [eventHandler, eventCondition, eventName]);
}
